  app.post('/api/admin/products',{preHandler:requirePermission('products.create')},async(request,reply)=>{const parsed=productSchema.safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Producto inválido.',details:parsed.error.flatten()});const p=parsed.data;if(!canAccessBrand(request,p.brandId))return reply.code(403).send({error:'Sin acceso.'});const hasVariants=p.variants.length>0,productStock=hasVariants?0:p.stockQty,productTrack=hasVariants?0:(p.trackStock?1:0);const conn=await pool.getConnection();try{await conn.beginTransaction();const[r]=await conn.query<ResultSetHeader>(`INSERT INTO products (brand_id,category_id,name,slug,short_description,description,seo_title,seo_description,sku,price,compare_at_price,wholesale_enabled,wholesale_price,wholesale_min_qty,stock_qty,low_stock_threshold,track_stock,featured,collection_featured,active,sort_order,image_url,image_zoom,image_position_x,image_position_y,image_blend_mode) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[p.brandId,p.categoryId||null,p.name,p.slug,p.shortDescription||null,p.description||null,p.seoTitle||null,p.seoDescription||null,p.sku,p.price,p.compareAtPrice??null,p.wholesaleEnabled?1:0,p.wholesalePrice??null,p.wholesaleMinQty,productStock,p.lowStockThreshold,productTrack,p.featured?1:0,p.collectionFeatured?1:0,p.active?1:0,p.sortOrder,p.imageUrl||null,p.imageZoom,p.imagePositionX,p.imagePositionY,p.imageBlendMode]);const id=Number(r.insertId);await saveProductChildren(conn,id,p.images,p.variants);await conn.commit();await audit(request,'product.create','product',id,{name:p.name,brand:p.brandId});const product=await loadAdminProduct(id);return reply.code(201).send({id,product});}catch(e:any){await conn.rollback();const duplicate=e?.code==='ER_DUP_ENTRY';return reply.code(400).send({code:duplicate?'DUPLICATE_SKU':'PRODUCT_SAVE_FAILED',error:duplicate?'Ese SKU ya está siendo utilizado.':(e.message||'No se pudo guardar.')});}finally{conn.release();}});
  app.put('/api/admin/products/:id',{preHandler:requirePermission('products.edit')},async(request,reply)=>{const id=Number((request.params as any).id);const parsed=productSchema.safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Producto inválido.',details:parsed.error.flatten()});const p=parsed.data;const[original]=await pool.query<any[]>('SELECT brand_id brandId,price FROM products WHERE id=? LIMIT 1',[id]);if(!original.length)return reply.code(404).send({error:'Producto inexistente.'});if(!canAccessBrand(request,original[0].brandId)||!canAccessBrand(request,p.brandId))return reply.code(403).send({error:'Sin acceso.'});const[[variantCount]]=await pool.query<any[]>('SELECT COUNT(*) total FROM product_variants WHERE product_id=? AND archived=0',[id]);if(Number(variantCount.total)>0&&p.variants.length===0&&!p.confirmVariantArchive)return reply.code(409).send({code:'VARIANT_ARCHIVE_CONFIRM_REQUIRED',error:`Este producto tiene ${variantCount.total} variantes activas. Confirmá la conversión para archivarlas.`});const hasVariants=p.variants.length>0,productStock=hasVariants?0:p.stockQty,productTrack=hasVariants?0:(p.trackStock?1:0);const conn=await pool.getConnection();try{await conn.beginTransaction();await conn.query(`UPDATE products SET brand_id=?,category_id=?,name=?,slug=?,short_description=?,description=?,seo_title=?,seo_description=?,sku=?,price=?,compare_at_price=?,wholesale_enabled=?,wholesale_price=?,wholesale_min_qty=?,stock_qty=?,low_stock_threshold=?,track_stock=?,featured=?,collection_featured=?,active=?,sort_order=?,image_url=?,image_zoom=?,image_position_x=?,image_position_y=?,image_blend_mode=? WHERE id=?`,[p.brandId,p.categoryId||null,p.name,p.slug,p.shortDescription||null,p.description||null,p.seoTitle||null,p.seoDescription||null,p.sku,p.price,p.compareAtPrice??null,p.wholesaleEnabled?1:0,p.wholesalePrice??null,p.wholesaleMinQty,productStock,p.lowStockThreshold,productTrack,p.featured?1:0,p.collectionFeatured?1:0,p.active?1:0,p.sortOrder,p.imageUrl||null,p.imageZoom,p.imagePositionX,p.imagePositionY,p.imageBlendMode,id]);await saveProductChildren(conn,id,p.images,p.variants);await conn.commit();await audit(request,'product.update','product',id,{name:p.name,brand:p.brandId,price:{from:Number(original[0].price),to:p.price}});const product=await loadAdminProduct(id);return{ok:true,product};}catch(e:any){await conn.rollback();const duplicate=e?.code==='ER_DUP_ENTRY';return reply.code(400).send({code:duplicate?'DUPLICATE_SKU':'PRODUCT_SAVE_FAILED',error:duplicate?'Ese SKU ya está siendo utilizado.':(e.message||'No se pudo guardar.')});}finally{conn.release();}});
  app.put('/api/admin/products/reorder',{preHandler:requirePermission('products.edit')},async(request,reply)=>{const parsed=z.object({items:z.array(z.object({id:z.number().int().positive(),sortOrder:z.number().int().min(0).max(999999)})).min(1).max(1000)}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Orden inválido.'});const conn=await pool.getConnection();try{await conn.beginTransaction();for(const item of parsed.data.items){const[rows]=await conn.query<RowDataPacket[]>('SELECT brand_id brandId FROM products WHERE id=?',[item.id]);if(rows.length&&!canAccessBrand(request,String(rows[0].brandId)))throw new Error('Sin acceso.');await conn.query('UPDATE products SET sort_order=? WHERE id=?',[item.sortOrder,item.id]);}await conn.commit();await audit(request,'product.reorder','product','bulk',{count:parsed.data.items.length});return{ok:true};}catch(e:any){await conn.rollback();return reply.code(403).send({error:e.message||'No se pudo guardar el orden.'});}finally{conn.release();}});

  app.put('/api/admin/wholesale/:id',{preHandler:requirePermission('products.price')},async(request,reply)=>{
    const id=Number((request.params as any).id);
    const parsed=z.object({
      wholesaleEnabled:z.boolean(),
      wholesalePrice:z.number().nonnegative().nullable(),
      wholesaleMinQty:z.number().int().min(1).max(9999),
      variants:z.array(z.object({id:z.number().int().positive(),wholesalePrice:z.number().nonnegative().nullable()})).max(80).default([]),
    }).safeParse(request.body);
    if(!parsed.success)return reply.code(400).send({error:'Configuración mayorista inválida.'});
    const[products]=await pool.query<any[]>('SELECT brand_id brandId,name FROM products WHERE id=? LIMIT 1',[id]);
    if(!products.length)return reply.code(404).send({error:'Producto inexistente.'});
    if(!canAccessBrand(request,products[0].brandId))return reply.code(403).send({error:'Sin acceso.'});
    const conn=await pool.getConnection();
    try{
      await conn.beginTransaction();
      await conn.query('UPDATE products SET wholesale_enabled=?,wholesale_price=?,wholesale_min_qty=? WHERE id=?',[parsed.data.wholesaleEnabled?1:0,parsed.data.wholesalePrice,parsed.data.wholesaleMinQty,id]);
      for(const variant of parsed.data.variants){
        const[result]=await conn.query<ResultSetHeader>('UPDATE product_variants SET wholesale_price=? WHERE id=? AND product_id=? AND archived=0',[variant.wholesalePrice,variant.id,id]);
        if(!result.affectedRows)throw new Error('Una variante mayorista ya no pertenece a este producto. Recargá la pantalla.');
      }
      await conn.commit();
      await audit(request,'product.wholesale','product',id,{enabled:parsed.data.wholesaleEnabled,minQty:parsed.data.wholesaleMinQty,variants:parsed.data.variants.length});
      const product=await loadAdminProduct(id);
      return{ok:true,product};
    }catch(e:any){
      await conn.rollback();
      return reply.code(400).send({error:e.message||'No se pudo guardar el precio mayorista.'});
    }finally{conn.release();}
  });

  app.post('/api/admin/products/:id/stock',{preHandler:requirePermission('inventory.adjust')},async(request,reply)=>{const id=Number((request.params as any).id);const parsed=z.object({delta:z.number().int().refine(n=>n!==0),note:z.string().max(255).optional(),variantId:z.number().int().positive().optional(),movementType:z.enum(['in','out','correction']).optional()}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Ajuste inválido.'});const conn=await pool.getConnection();try{await conn.beginTransaction();const[rows]=await conn.query<RowDataPacket[]>('SELECT brand_id brandId,stock_qty stockQty FROM products WHERE id=? FOR UPDATE',[id]);const product=rows[0];if(!product)throw new Error('Producto no encontrado.');if(!canAccessBrand(request,String(product.brandId)))throw new Error('Sin acceso.');const[vcRows]=await conn.query<RowDataPacket[]>('SELECT COUNT(*) total FROM product_variants WHERE product_id=? AND archived=0',[id]);let next=0,before=0;if(Number(vcRows[0]?.total||0)>0){if(!parsed.data.variantId)throw new Error('Elegí una variante para ajustar el stock.');const[vs]=await conn.query<RowDataPacket[]>('SELECT id,stock_qty stockQty FROM product_variants WHERE id=? AND product_id=? AND archived=0 FOR UPDATE',[parsed.data.variantId,id]);if(!vs.length)throw new Error('Variante no encontrada.');before=Number(vs[0].stockQty);next=before+parsed.data.delta;if(next<0)throw new Error('El stock no puede quedar negativo.');await conn.query('UPDATE product_variants SET stock_qty=? WHERE id=?',[next,parsed.data.variantId]);await conn.query(`INSERT INTO stock_movements (product_id,variant_id,delta,balance_after,reason,note,actor_admin_id) VALUES (?,?,?,?,'manual_adjustment',?,?)`,[id,parsed.data.variantId,parsed.data.delta,next,parsed.data.note||'Ajuste manual',request.user.id]);}else{before=Number(product.stockQty);next=before+parsed.data.delta;if(next<0)throw new Error('El stock no puede quedar negativo.');await conn.query('UPDATE products SET stock_qty=? WHERE id=?',[next,id]);await conn.query(`INSERT INTO stock_movements (product_id,delta,balance_after,reason,note,actor_admin_id) VALUES (?,?,?,'manual_adjustment',?,?)`,[id,parsed.data.delta,next,parsed.data.note||'Ajuste manual',request.user.id]);}await conn.commit();await audit(request,'stock.adjust','product',id,{variantId:parsed.data.variantId||null,before,delta:parsed.data.delta,after:next,note:parsed.data.note||'Ajuste manual'});return{ok:true,stockQty:next};}catch(e:any){await conn.rollback();return reply.code(e.message==='Sin acceso.'?403:400).send({error:e.message||'No se pudo ajustar.'});}finally{conn.release();}});
  app.get('/api/admin/stock-movements',{preHandler:requirePermission('inventory.view')},async(request,reply)=>{const{brand}=request.query as {brand?:string};const effective=effectiveBrand(request,brand||null);if(effective==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const params:any[]=[];let where='WHERE 1=1';if(effective){where+=' AND p.brand_id=?';params.push(effective);}const[rows]=await pool.query<any[]>(`SELECT sm.id,sm.variant_id AS variantId,sm.delta,sm.balance_after AS balanceAfter,sm.reason,sm.note,sm.created_at AS createdAt,p.name AS productName,p.sku,p.brand_id AS brandId,v.value AS variantValue,v.sku AS variantSku,o.code AS orderCode,a.name AS actorName FROM stock_movements sm JOIN products p ON p.id=sm.product_id LEFT JOIN product_variants v ON v.id=sm.variant_id LEFT JOIN orders o ON o.id=sm.order_id LEFT JOIN admins a ON a.id=sm.actor_admin_id ${where} ORDER BY sm.created_at DESC LIMIT 500`,params);return rows;});

  app.get('/api/admin/orders',{preHandler:requirePermission('orders.view')},async(request,reply)=>{const{brand,status,search}=request.query as {brand?:string;status?:string;search?:string};const effective=effectiveBrand(request,brand||null);if(effective==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const params:any[]=[];const conditions=['1=1'];if(effective){conditions.push('EXISTS (SELECT 1 FROM order_items x WHERE x.order_id=o.id AND x.brand_id=?)');params.push(effective);}if(status){conditions.push('o.status=?');params.push(status);}if(search?.trim()){conditions.push('(o.code LIKE ? OR o.customer_name LIKE ? OR o.customer_phone LIKE ?)');const term=`%${search.trim()}%`;params.push(term,term,term);}const[orders]=await pool.query<any[]>(`SELECT o.id,o.code,o.customer_name AS customerName,o.customer_phone AS customerPhone,o.customer_email AS customerEmail,o.delivery_type AS deliveryType,o.address,o.notes,o.internal_note AS internalNote,o.total,o.status,o.reserved_until AS reservedUntil,o.created_at AS createdAt,o.updated_at AS updatedAt FROM orders o WHERE ${conditions.join(' AND ')} ORDER BY o.created_at DESC LIMIT 500`,params);if(!orders.length)return[];const ids=orders.map(o=>o.id);const ph=ids.map(()=>'?').join(',');const[items]=await pool.query<any[]>(`SELECT order_id AS orderId,brand_id AS brandId,product_name AS productName,sku,variant_name AS variantName,variant_value AS variantValue,variant_sku AS variantSku,image_url AS imageUrl,unit_price AS unitPrice,qty,line_total AS lineTotal FROM order_items WHERE order_id IN (${ph}) ORDER BY id`,ids);const[eventRows]=await pool.query<any[]>(`SELECT order_id AS orderId,from_status AS fromStatus,to_status AS toStatus,note,created_at AS createdAt FROM order_events WHERE order_id IN (${ph}) ORDER BY created_at`,ids);const grouped=new Map<number,any[]>(),events=new Map<number,any[]>();items.forEach(i=>grouped.set(Number(i.orderId),[...(grouped.get(Number(i.orderId))||[]),i]));eventRows.forEach(e=>events.set(Number(e.orderId),[...(events.get(Number(e.orderId))||[]),e]));return orders.map(o=>{const allItems=grouped.get(Number(o.id))||[];const visibleItems=effective?allItems.filter(i=>i.brandId===effective):allItems;const brands=new Set(allItems.map(i=>i.brandId));const visibleTotal=effective?visibleItems.reduce((s,i)=>s+Number(i.lineTotal||0),0):Number(o.total);return{...o,total:visibleTotal,orderTotal:Number(o.total),items:visibleItems,events:events.get(Number(o.id))||[],mixedBrands:brands.size>1,canOperate:!request.user.brandScope||(brands.size===1&&brands.has(request.user.brandScope))};});});
  app.patch('/api/admin/orders/:id/status',{preHandler:requirePermission('orders.update_status')},async(request,reply)=>{const id=Number((request.params as any).id);const parsed=z.object({status:z.enum(['confirmed','preparing','ready','completed','cancelled'])}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Estado inválido.'});if(!(await mayOperateOrder(request,id)))return reply.code(403).send({error:'Este pedido incluye una marca fuera de tu alcance. Necesitás acceso global para cambiar su estado.'});const[orders]=await pool.query<any[]>('SELECT id,status FROM orders WHERE id=? LIMIT 1',[id]);if(!orders.length)return reply.code(404).send({error:'Pedido inexistente.'});const from=String(orders[0].status),to=parsed.data.status;if(to==='cancelled'&&!hasPermission(request,'orders.cancel'))return reply.code(403).send({error:'No tenés permiso para cancelar pedidos.'});if(!canTransitionOrder(from,to))return reply.code(409).send({code:'INVALID_ORDER_TRANSITION',error:`No se puede pasar de ${from} a ${to}.`});if(to==='cancelled'){const restored=await restoreStockForOrder(id,'cancel_restore',request.user.id);if(!restored)return reply.code(409).send({error:'El pedido ya estaba cancelado o vencido.'});await pool.query('INSERT INTO order_events (order_id,from_status,to_status,actor_admin_id) VALUES (?,?,?,?)',[id,from,to,request.user.id]);await audit(request,'order.cancel','order',id,{from,to});return{ok:true};}await pool.query('UPDATE orders SET status=? WHERE id=?',[to,id]);await pool.query('INSERT INTO order_events (order_id,from_status,to_status,actor_admin_id) VALUES (?,?,?,?)',[id,from,to,request.user.id]);await audit(request,'order.status','order',id,{from,to});return{ok:true};});
  app.put('/api/admin/orders/:id/note',{preHandler:requirePermission('orders.update_status')},async(request,reply)=>{const id=Number((request.params as any).id);if(!(await mayOperateOrder(request,id)))return reply.code(403).send({error:'Sin acceso a este pedido.'});const parsed=z.object({note:z.string().max(2000)}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Nota inválida.'});await pool.query('UPDATE orders SET internal_note=? WHERE id=?',[parsed.data.note||null,id]);await audit(request,'order.note','order',id,{note:parsed.data.note});return{ok:true};});

  app.get('/api/admin/customers',{preHandler:requirePermission('customers.view')},async(request,reply)=>{const{brand}=request.query as {brand?:string};const effective=effectiveBrand(request,brand||null);if(effective==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const params:any[]=[];const itemWhere=effective?'AND oi.brand_id=?':'';if(effective)params.push(effective);const[rows]=await pool.query<any[]>(`SELECT o.customer_phone phone,SUBSTRING_INDEX(GROUP_CONCAT(o.customer_name ORDER BY o.created_at DESC SEPARATOR '||'),'||',1) name,SUBSTRING_INDEX(GROUP_CONCAT(COALESCE(o.customer_email,'') ORDER BY o.created_at DESC SEPARATOR '||'),'||',1) email,COUNT(DISTINCT o.id) orders,COALESCE(SUM(oi.line_total),0) totalSpent,MAX(o.created_at) lastOrder,SUBSTRING_INDEX(GROUP_CONCAT(o.delivery_type ORDER BY o.created_at DESC SEPARATOR ','),',',1) lastDelivery FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.status IN ${sellStatuses} ${itemWhere} GROUP BY o.customer_phone ORDER BY totalSpent DESC,lastOrder DESC LIMIT 1000`,params);return rows.map(r=>({...r,orders:Number(r.orders||0),totalSpent:Number(r.totalSpent||0),avgTicket:Number(r.orders)?Number(r.totalSpent||0)/Number(r.orders):0}));});
  app.get('/api/admin/customers/:phone',{preHandler:requirePermission('customers.view')},async(request,reply)=>{const phone=decodeURIComponent(String((request.params as any).phone||''));const{brand}=request.query as {brand?:string};const effective=effectiveBrand(request,brand||null);if(effective==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const params:any[]=[phone];const brandJoin=effective?'AND oi.brand_id=?':'';if(effective)params.push(effective);const[orders]=await pool.query<any[]>(`SELECT o.id,o.code,o.created_at createdAt,o.delivery_type deliveryType,o.status,SUM(oi.line_total) totalSpent FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.customer_phone=? AND o.status IN ${sellStatuses} ${brandJoin} GROUP BY o.id ORDER BY o.created_at DESC LIMIT 30`,params);const[topProducts]=await pool.query<any[]>(`SELECT oi.product_name productName,COALESCE(oi.variant_value,'') variantValue,SUM(oi.qty) qty FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE o.customer_phone=? AND o.status IN ${sellStatuses} ${brandJoin} GROUP BY oi.product_name,oi.variant_value ORDER BY qty DESC LIMIT 6`,params);const customer=orders.length?{phone,name:'',orders:orders.length,totalSpent:orders.reduce((sum:number,o:any)=>sum+Number(o.totalSpent||0),0),avgTicket:0,lastOrder:orders[0].createdAt,lastDelivery:orders[0].deliveryType}:null;if(customer)customer.avgTicket=customer.totalSpent/customer.orders;return{customer,orders:orders.map(o=>({...o,totalSpent:Number(o.totalSpent||0)})),topProducts:topProducts.map(p=>({...p,qty:Number(p.qty||0)}))};});

  app.get('/api/admin/notifications',{preHandler:requirePermission('dashboard.view')},async(request,reply)=>{const{brand}=request.query as {brand?:string};const scope=effectiveBrand(request,brand||null);if(scope==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const pParams=scope?[scope]:[];const productWhere=scope?'AND p.brand_id=?':'';const[[low]]=await pool.query<any[]>(`SELECT COUNT(*) total FROM products p WHERE p.active=1 ${productWhere} AND ((NOT EXISTS(SELECT 1 FROM product_variants vx WHERE vx.product_id=p.id AND vx.active=1 AND vx.archived=0) AND p.track_stock=1 AND p.stock_qty<=p.low_stock_threshold) OR EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id AND v.active=1 AND v.archived=0 AND v.track_stock=1 AND v.stock_qty<=v.low_stock_threshold))`,pParams);const itemClause=scope?'AND EXISTS(SELECT 1 FROM order_items oi WHERE oi.order_id=o.id AND oi.brand_id=?)':'';const[[pending]]=await pool.query<any[]>(`SELECT COUNT(*) total FROM orders o WHERE o.status='pending' ${itemClause}`,pParams);const[[stale]]=await pool.query<any[]>(`SELECT COUNT(*) total FROM orders o WHERE o.status='pending' AND o.created_at<DATE_SUB(NOW(),INTERVAL 30 MINUTE) ${itemClause}`,pParams);const[[ready]]=await pool.query<any[]>(`SELECT COUNT(*) total FROM orders o WHERE o.status='ready' ${itemClause}`,pParams);const[[noImage]]=await pool.query<any[]>(`SELECT COUNT(*) total FROM products p WHERE p.active=1 AND (p.image_url IS NULL OR p.image_url='') ${productWhere}`,pParams);const items=[{id:'pending',type:'orders',severity:'info',title:`${Number(pending.total)} pedidos pendientes`,count:Number(pending.total),href:'/admin/pedidos?status=pending'},{id:'stale',type:'orders',severity:'warning',title:`${Number(stale.total)} pendientes hace +30 min`,count:Number(stale.total),href:'/admin/pedidos?status=pending'},{id:'ready',type:'orders',severity:'success',title:`${Number(ready.total)} pedidos listos`,count:Number(ready.total),href:'/admin/pedidos?status=ready'},{id:'low',type:'stock',severity:'warning',title:`${Number(low.total)} alertas de stock`,count:Number(low.total),href:'/admin/stock?low=1'},{id:'images',type:'catalog',severity:'info',title:`${Number(noImage.total)} productos sin foto`,count:Number(noImage.total),href:'/admin/productos?missingImage=1'}].filter(x=>x.count>0);return{total:items.reduce((s,x)=>s+x.count,0),items};});

  app.get('/api/admin/search',{preHandler:requireAdmin},async(request,reply)=>{const raw=request.query as any;const q=String(raw.q||'').trim();if(q.length<2)return{products:[],orders:[],customers:[]};const scope=effectiveBrand(request,raw.brand||null);if(scope==='__forbidden__')return reply.code(403).send({error:'Sin acceso.'});const term=`%${q}%`,pParams:any[]=[term,term];let pWhere='';if(scope){pWhere='AND brand_id=?';pParams.push(scope);}const[products]=await pool.query<any[]>(`SELECT id,name,sku,brand_id brandId FROM products WHERE (name LIKE ? OR sku LIKE ?) ${pWhere} ORDER BY name LIMIT 6`,pParams);const oParams:any[]=[term,term,term];let oWhere='';if(scope){oWhere='AND EXISTS(SELECT 1 FROM order_items oi WHERE oi.order_id=o.id AND oi.brand_id=?)';oParams.push(scope);}const[orders]=await pool.query<any[]>(`SELECT o.id,o.code,o.customer_name customerName,o.status FROM orders o WHERE (o.code LIKE ? OR o.customer_name LIKE ? OR o.customer_phone LIKE ?) ${oWhere} ORDER BY o.created_at DESC LIMIT 6`,oParams);const cParams:any[]=[term,term];let cWhere='';if(scope){cWhere='AND EXISTS(SELECT 1 FROM order_items oi WHERE oi.order_id=o.id AND oi.brand_id=?)';cParams.push(scope);}const[cust]=await pool.query<any[]>(`SELECT o.customer_phone phone,SUBSTRING_INDEX(GROUP_CONCAT(o.customer_name ORDER BY o.created_at DESC SEPARATOR '||'),'||',1) name FROM orders o WHERE (o.customer_name LIKE ? OR o.customer_phone LIKE ?) ${cWhere} GROUP BY o.customer_phone LIMIT 6`,cParams);return{products,orders,customers:cust};});

  app.get('/api/admin/settings',{preHandler:requirePermission('settings.manage')},async()=>{const[rows]=await pool.query<any[]>('SELECT setting_key settingKey,setting_value settingValue FROM site_settings ORDER BY setting_key');const settings=Object.fromEntries(rows.map(r=>[r.settingKey,r.settingValue]));const[brands]=await pool.query<any[]>('SELECT id,name,whatsapp,instagram,email FROM brands ORDER BY id');return{settings,brands};});
  app.put('/api/admin/settings',{preHandler:requirePermission('settings.manage')},async(request,reply)=>{const schema=z.object({settings:z.record(z.string(),z.string().max(2000)).default({}),brands:z.array(z.object({id:z.enum(['amargos','enyerbados']),whatsapp:z.string().max(40).nullable().optional(),instagram:z.string().max(120).nullable().optional(),email:z.string().max(190).nullable().optional()})).max(2).default([])});const parsed=schema.safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Configuración inválida.'});const allowed=new Set(['order_whatsapp','hero_amargos','hero_enyerbados','shipping_note','pickup_note','instagram_feed_url','store_status','announcement','reservation_minutes']);const conn=await pool.getConnection();try{await conn.beginTransaction();for(const[key,value]of Object.entries(parsed.data.settings)){if(allowed.has(key))await conn.query('INSERT INTO site_settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)',[key,value]);}for(const b of parsed.data.brands){if(!canAccessBrand(request,b.id))continue;await conn.query('UPDATE brands SET whatsapp=?,instagram=?,email=? WHERE id=?',[b.whatsapp||null,b.instagram||null,b.email||null,b.id]);}await conn.commit();await audit(request,'settings.update','settings','global',{keys:Object.keys(parsed.data.settings)});return{ok:true};}catch(e:any){await conn.rollback();return reply.code(400).send({error:e.message||'No se pudo guardar.'});}finally{conn.release();}});

