  app.post('/api/admin/admins',{preHandler:requirePermission('admins.manage')},async(request,reply)=>{const parsed=z.object({name:z.string().min(2).max(120),email:z.string().email(),password:z.string().min(8).max(120),role:z.enum(['superadmin','manager','operator']),brandScope:z.enum(['amargos','enyerbados']).nullable().optional(),active:z.boolean().default(true)}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Administrador inválido.'});if(request.user.role!=='superadmin')return reply.code(403).send({error:'Solo un superadmin puede administrar usuarios.'});const hash=await bcrypt.hash(parsed.data.password,12);try{const[r]=await pool.query<ResultSetHeader>('INSERT INTO admins (name,email,password_hash,role,brand_scope,active) VALUES (?,?,?,?,?,?)',[parsed.data.name,parsed.data.email.toLowerCase(),hash,parsed.data.role,parsed.data.brandScope||null,parsed.data.active?1:0]);await audit(request,'admin.create','admin',r.insertId,{email:parsed.data.email,role:parsed.data.role,brandScope:parsed.data.brandScope||null});return reply.code(201).send({id:Number(r.insertId)});}catch(e:any){return reply.code(400).send({error:e.code==='ER_DUP_ENTRY'?'Ese email ya existe.':'No se pudo crear el administrador.'});}});
  app.put('/api/admin/admins/:id',{preHandler:requirePermission('admins.manage')},async(request,reply)=>{if(request.user.role!=='superadmin')return reply.code(403).send({error:'Solo un superadmin puede administrar usuarios.'});const id=Number((request.params as any).id);const parsed=z.object({name:z.string().min(2).max(120),role:z.enum(['superadmin','manager','operator']),brandScope:z.enum(['amargos','enyerbados']).nullable().optional(),active:z.boolean(),password:z.string().min(8).max(120).optional()}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'Datos inválidos.'});if(id===request.user.id&&!parsed.data.active)return reply.code(409).send({error:'No podés desactivar tu propio usuario.'});const hash=parsed.data.password?await bcrypt.hash(parsed.data.password,12):null;if(hash)await pool.query('UPDATE admins SET name=?,role=?,brand_scope=?,active=?,password_hash=? WHERE id=?',[parsed.data.name,parsed.data.role,parsed.data.brandScope||null,parsed.data.active?1:0,hash,id]);else await pool.query('UPDATE admins SET name=?,role=?,brand_scope=?,active=? WHERE id=?',[parsed.data.name,parsed.data.role,parsed.data.brandScope||null,parsed.data.active?1:0,id]);await audit(request,'admin.update','admin',id,{role:parsed.data.role,brandScope:parsed.data.brandScope||null,active:parsed.data.active});return{ok:true};});

  app.get('/api/admin/banners',{preHandler:requirePermission('content.manage')},async(request)=>{const params:any[]=[];let where='';if(request.user.brandScope){where='WHERE brand_id IS NULL OR brand_id=?';params.push(request.user.brandScope);}const[rows]=await pool.query<any[]>(`SELECT id,brand_id AS brandId,eyebrow,title,subtitle,image_url AS imageUrl,mobile_image_url AS mobileImageUrl,object_position_desktop AS objectPositionDesktop,object_position_mobile AS objectPositionMobile,cta_label AS ctaLabel,href,sort_order AS sortOrder,active FROM home_banners ${where} ORDER BY sort_order,id`,params);return rows.map(r=>({...r,active:Boolean(r.active)}));});
