  app.delete('/api/admin/banners/:id',{preHandler:requirePermission('content.manage')},async(request,reply)=>{const id=Number((request.params as any).id);const[rows]=await pool.query<any[]>('SELECT brand_id brandId,title FROM home_banners WHERE id=?',[id]);if(!rows.length)return reply.code(404).send({error:'Banner inexistente.'});if(rows[0].brandId&&!canAccessBrand(request,rows[0].brandId))return reply.code(403).send({error:'Sin acceso.'});await pool.query('DELETE FROM home_banners WHERE id=?',[id]);await audit(request,'banner.delete','banner',id,{title:rows[0].title});return{ok:true};});

  app.get('/api/admin/media',{preHandler:requirePermission('media.manage')},async()=>{const[rows]=await pool.query<any[]>(`SELECT m.id,m.url,m.file_name AS fileName,m.mime_type AS mimeType,m.size_bytes AS sizeBytes,m.width,m.height,m.alt_text AS altText,m.created_at AS createdAt,a.name AS uploadedByName FROM media_assets m LEFT JOIN admins a ON a.id=m.uploaded_by ORDER BY m.created_at DESC LIMIT 1000`);return rows;});
  app.get('/api/admin/media/:id/usage',{preHandler:requirePermission('media.manage')},async(request,reply)=>{const id=Number((request.params as any).id);const[rows]=await pool.query<any[]>('SELECT url FROM media_assets WHERE id=?',[id]);if(!rows.length)return reply.code(404).send({error:'Archivo inexistente.'});const url=rows[0].url;const queries=await Promise.all([pool.query<any[]>('SELECT id,name label FROM products WHERE image_url=? LIMIT 20',[url]),pool.query<any[]>('SELECT pi.id,p.name label FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE pi.image_url=? LIMIT 20',[url]),pool.query<any[]>('SELECT v.id,p.name label,v.value extra FROM product_variants v JOIN products p ON p.id=v.product_id WHERE v.image_url=? LIMIT 20',[url]),pool.query<any[]>('SELECT vi.id,p.name label,v.value extra FROM product_variant_images vi JOIN product_variants v ON v.id=vi.variant_id JOIN products p ON p.id=v.product_id WHERE vi.image_url=? LIMIT 20',[url]),pool.query<any[]>('SELECT id,name label FROM categories WHERE image_url=? LIMIT 20',[url]),pool.query<any[]>('SELECT id,title label FROM home_banners WHERE image_url=? OR mobile_image_url=? LIMIT 20',[url,url]),pool.query<any[]>('SELECT id,name label FROM materos_locations WHERE image_url=? LIMIT 20',[url])]);return{products:queries[0][0],productGallery:queries[1][0],variants:queries[2][0],variantGallery:queries[3][0],categories:queries[4][0],banners:queries[5][0],materos:queries[6][0]};});
  app.delete('/api/admin/media/:id',{preHandler:requirePermission('media.manage')},async(request,reply)=>{const id=Number((request.params as any).id);const[rows]=await pool.query<any[]>('SELECT url,file_name fileName FROM media_assets WHERE id=? LIMIT 1',[id]);if(!rows.length)return reply.code(404).send({error:'Archivo inexistente.'});const{url,fileName}=rows[0];const counts=await Promise.all([pool.query<any[]>('SELECT COUNT(*) total FROM products WHERE image_url=?',[url]),pool.query<any[]>('SELECT COUNT(*) total FROM product_images WHERE image_url=?',[url]),pool.query<any[]>('SELECT COUNT(*) total FROM product_variants WHERE image_url=?',[url]),pool.query<any[]>('SELECT COUNT(*) total FROM product_variant_images WHERE image_url=?',[url]),pool.query<any[]>('SELECT COUNT(*) total FROM categories WHERE image_url=?',[url]),pool.query<any[]>('SELECT COUNT(*) total FROM home_banners WHERE image_url=? OR mobile_image_url=?',[url,url]),pool.query<any[]>('SELECT COUNT(*) total FROM materos_locations WHERE image_url=?',[url])]);const used=counts.reduce((s,r)=>s+Number((r[0] as any[])[0]?.total||0),0);if(used>0)return reply.code(409).send({code:'MEDIA_IN_USE',error:'La imagen está en uso. Revisá sus usos antes de eliminarla.'});const conn=await pool.getConnection();try{await conn.beginTransaction();await conn.query('DELETE FROM media_assets WHERE id=?',[id]);if(String(url).startsWith('/uploads/')){const root=getUploadRoot();const diskPath=path.resolve(root,String(fileName));if(diskPath.startsWith(root+path.sep)){try{await fs.unlink(diskPath);}catch(e:any){if(e?.code!=='ENOENT')throw e;}}}await conn.commit();await audit(request,'media.delete','media',id,{url});return{ok:true};}catch(e:any){await conn.rollback();return reply.code(500).send({error:'No se pudo eliminar el archivo de forma segura.'});}finally{conn.release();}});

  app.get('/api/admin/faqs',{preHandler:requirePermission('content.manage')},async()=>{const[rows]=await pool.query<any[]>('SELECT id,question,answer,keywords,category,sort_order AS sortOrder,active FROM faq_items ORDER BY sort_order,id');return rows.map(r=>({...r,active:Boolean(r.active)}));});
  app.post('/api/admin/faqs',{preHandler:requirePermission('content.manage')},async(request,reply)=>{const parsed=z.object({question:z.string().min(2).max(220),answer:z.string().min(2).max(4000),keywords:z.string().max(500).optional().default(''),category:z.string().min(2).max(80).default('General'),sortOrder:z.number().int().min(0).default(0),active:z.boolean().default(true)}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'FAQ inválida.'});const f=parsed.data;const[r]=await pool.query<ResultSetHeader>('INSERT INTO faq_items (question,answer,keywords,category,sort_order,active) VALUES (?,?,?,?,?,?)',[f.question,f.answer,f.keywords,f.category,f.sortOrder,f.active?1:0]);await audit(request,'faq.create','faq',r.insertId,{question:f.question});return{ok:true,id:Number(r.insertId)};});
  app.put('/api/admin/faqs/:id',{preHandler:requirePermission('content.manage')},async(request,reply)=>{const id=Number((request.params as any).id);const parsed=z.object({question:z.string().min(2).max(220),answer:z.string().min(2).max(4000),keywords:z.string().max(500).optional().default(''),category:z.string().min(2).max(80).default('General'),sortOrder:z.number().int().min(0).default(0),active:z.boolean().default(true)}).safeParse(request.body);if(!parsed.success)return reply.code(400).send({error:'FAQ inválida.'});const f=parsed.data;await pool.query('UPDATE faq_items SET question=?,answer=?,keywords=?,category=?,sort_order=?,active=? WHERE id=?',[f.question,f.answer,f.keywords,f.category,f.sortOrder,f.active?1:0,id]);await audit(request,'faq.update','faq',id,{question:f.question});return{ok:true};});
